```openscad
// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on XY plane, pockets open upward (+Z)

// ---------- Block ----------
block_x = 80;     // block length along X (mm)
block_y = 26;     // block width along Y (mm)
block_z = 32;     // block height (mm)

// ---------- Pockets ----------
pocket_n     = 4;     // number of cuvette pockets
pocket_w     = 13.2;  // pocket size in X and Y (square, mm)
pocket_depth = 27;    // pocket depth from top face (mm)
pocket_pitch = 18.2;  // centre-to-centre spacing along X (mm)
floor_t      = block_z - pocket_depth; // remaining floor thickness = 5 mm

// ---------- Misc ----------
eps = 0.5;        // overcut past the top face to avoid coplanar faces
$fn = 64;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square pockets, centred on the block
    for (i = [0 : pocket_n - 1]) {
        px = (i - (pocket_n - 1)/2) * pocket_pitch;
        translate([px - pocket_w/2, -pocket_w/2, floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}
```

