pocket_depth = 29;    // pocket depth from top face
pocket_pitch = 19.8;  // centre-to-centre spacing along X
floor_t      = block_z - pocket_depth;  // material below pockets (3 mm)

// ---------------- Misc ----------------
overcut = 0.5;      // extension of cutters past the top face
$fn = 64;

// X position of the first pocket centre so the row is centred on the block
first_x = -(pocket_count - 1) * pocket_pitch / 2;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Row of square cuvette pockets
    for (i = [0 : pocket_count - 1]) {
        translate([first_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + overcut]);
    }
}
