floor_t  = block_h - pocket_depth;                 // 5 mm floor below pockets
row_span = (n_pockets - 1) * pocket_pitch;         // first-to-last centre distance

$fn = 64;

difference() {
    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets, centred on the block
    for (i = [0 : n_pockets - 1]) {
        translate([-row_span/2 + i * pocket_pitch - pocket_w/2,
                   -pocket_w/2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + cut_extra]);
    }
