```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward (+Z)

// ---------------- Parameters ----------------
plate_len    = 160;   // base plate length (X)
plate_wid    = 35;    // base plate width (Y)
plate_thk    = 4;     // base plate thickness (Z)

upright_thk  = 12;    // upright block thickness (X)
upright_h    = 35;    // upright total height from bed (Z)

notch_r      = 7;     // cradle notch radius
notch_z      = upright_h; // notch centre height (on top edge)

eps          = 0.5;   // overcut for clean differences
$fn          = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? plate_len/2 - upright_thk : -plate_len/2,
                       -plate_wid/2, 0])
                cube([upright_thk, plate_wid, upright_h]);
    }

    // Semicircular cradle notches through each upright along X
    for (sx = [-1, 1])
        translate([sx > 0 ? plate_len/2 - upright_thk - eps : -plate_len/2 - eps,
                   0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = upright_thk + 2*eps);
}
