// Horizontal pipette rest
$fn = 96;

// --- Dimensions (mm) ---
base_len   = 140;  // base plate length (X)
base_wid   = 30;   // base plate width (Y)
base_th    = 5;    // base plate thickness (Z)
up_th      = 12;   // upright thickness (X)
up_h       = 40;   // upright height (top at z = 40)
notch_r    = 10;   // cradle notch radius
eps        = 0.5;  // cut overlap

// x-positions of upright centres (flush with plate ends)
up_x = [-(base_len/2 - up_th/2), (base_len/2 - up_th/2)];

difference() {
    union() {
        // base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_th]);
        // uprights
        for (x = up_x)
            translate([x - up_th/2, -base_wid/2, 0])
                cube([up_th, base_wid, up_h]);
    }
    // semicircular cradle notches, axis along X, centre at y=0, z=up_h
    for (x = up_x)
        translate([x - up_th/2 - eps, 0, up_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_th + 2*eps);
}
