```openscad
// Horizontal pipette rest
$fn = 96;

// Base plate
base_len   = 140;   // plate length along X
base_wid   = 35;    // plate width along Y
base_thk   = 4;     // plate thickness (Z)

// Uprights
up_thk     = 8;     // upright thickness along X
up_h       = 30;    // upright height (top at z = 30)

// Cradle notch
notch_r    = 7;     // semicircular notch radius, centre at (y=0, z=up_h)

eps        = 0.5;   // cutter overrun

module upright(xc) {
    difference() {
        translate([xc - up_thk/2, -base_wid/2, 0])
            cube([up_thk, base_wid, up_h]);
        // semicircular cradle notch running along X
        translate([xc - up_thk/2 - eps, 0, up_h])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}

union() {
    // base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // uprights flush with each end
    for (s = [-1, 1])
        upright(s * (base_len/2 - up_thk/2));
}
```

