```openscad
// Flat wrench for hexagonal reagent-bottle caps
// Print orientation: flat on bed, z = 0 to plate_t

$fn = 96;

// ---- Dimensions (mm) ----
plate_t      = 5;     // plate thickness (Z)
head_d       = 50;    // round head diameter, centred on origin
handle_w     = 14;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 120;   // handle end (X)
hex_af       = 32;    // hex hole size across flats
eps          = 0.5;   // overcut for clean differences

// Derived
hex_r = (hex_af / 2) / cos(30);   // hex circumradius (vertex distance)

difference() {
    // Plate body: head + handle
    union() {
        cylinder(d = head_d, h = plate_t);
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: vertices at 0,60,...deg -> flats parallel to X axis
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            polygon([for (i = [0:5]) [hex_r * cos(60 * i), hex_r * sin(60 * i)]]);
}
