// Tube label-writing holding block
// Block with a semicircular channel along X on the top face

// ---- Dimensions (mm) ----
block_len    = 50;   // block length along X
block_wid    = 24;   // block width along Y
block_ht     = 20;   // block height along Z
channel_d    = 10;   // channel diameter (semicircular cross-section)
channel_y    = 0;    // channel axis Y position
channel_z    = 20;   // channel axis Z position (on top surface)
cut_extra    = 1;    // overshoot of cutter past block end faces

$fn = 96;            // smoothness for curved surfaces

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular channel: full cylinder whose axis lies on the top face,
    // so only the lower half cuts into the block (5 mm deep)
    translate([-block_len/2 - cut_extra, channel_y, channel_z])
        rotate([0, 90, 0])
            cylinder(d = channel_d, h = block_len + 2*cut_extra);
}
