// Hex key organiser block
// Print orientation: base on XY plane, pockets open at top (+Z)

// ---------------- Parameters ----------------
block_len    = 74;    // block length along X (mm)
block_wid    = 18;    // block width along Y (mm)
block_ht     = 25;    // block height along Z (mm)

pocket_depth = 15;    // depth of each hex pocket from top face (mm)
pocket_pitch = 10;    // centre-to-centre spacing of pockets along X (mm)
pocket_flats = [2.4, 2.9, 3.4, 4.4, 5.4, 6.4]; // across-flats sizes, -X to +X (mm)

overcut      = 0.5;   // extra length of cutters past the top face (mm)

// ---------------- Derived ----------------
n_pockets = len(pocket_flats);
// Circumradius of a regular hexagon from its across-flats size
function hex_r(af) = af / sqrt(3);

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Hexagonal pockets along y = 0, centred on the block
    for (i = [0 : n_pockets - 1]) {
        x = (i - (n_pockets - 1) / 2) * pocket_pitch;
        // cylinder with $fn=6 puts vertices at 0°,60°... so two flats are parallel to X
        translate([x, 0, block_ht - pocket_depth])
            cylinder(r = hex_r(pocket_flats[i]),
                     h = pocket_depth + overcut,
                     $fn = 6);
    }
}
```

