// Flat spacer ring with 3 mounting through-holes
// Units: mm. Prints flat on the bed (z = 0), builds upward.

// ---------- Dimensions ----------
ring_thickness   = 3;     // ring height (Z)
outer_diameter   = 70;    // outer diameter of annulus
inner_diameter   = 42;    // inner (bore) diameter
hole_diameter    = 5.5;   // through-hole diameter
hole_circle_d    = 56;    // bolt circle diameter
hole_count       = 3;     // number of through-holes
first_hole_angle = 0;     // first hole on +X axis (degrees)

// ---------- Helpers ----------
eps   = 0.5;              // cutter overshoot past faces
$fn   = 128;              // smoothness for curved shapes

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -eps])
        cylinder(h = ring_thickness + 2 * eps, d = inner_diameter);

    // Through-holes on bolt circle
    for (i = [0 : hole_count - 1]) {
        a = first_hole_angle + i * 360 / hole_count;
        translate([hole_circle_d / 2 * cos(a), hole_circle_d / 2 * sin(a), -eps])
            cylinder(h = ring_thickness + 2 * eps, d = hole_diameter, $fn = 64);
    }
}
