// Glassware drying board
// Flat base plate with a 4 x 3 grid of vertical round pegs

$fn = 64;

// ---------- Base plate ----------
plate_x     = 129;   // plate length along X (mm)
plate_y     = 94;    // plate width along Y (mm)
plate_t     = 6;     // plate thickness (mm), z = 0 to 6

// ---------- Pegs ----------
peg_d       = 6;     // peg diameter (mm)
peg_top_z   = 36;    // top of pegs (mm)
peg_h       = peg_top_z - plate_t;  // peg height above plate (30 mm)
peg_nx      = 4;     // number of pegs along X
peg_ny      = 3;     // number of pegs along Y
peg_pitch   = 35;    // centre-to-centre spacing in X and Y (mm)
overlap     = 0.5;   // peg sinks into plate for a clean union (mm)

// Grid origin offsets so the grid is centred on the plate
grid_x0 = -(peg_nx - 1) * peg_pitch / 2;
grid_y0 = -(peg_ny - 1) * peg_pitch / 2;

union() {
    // Base plate, centred in XY, resting on z = 0
    translate([-plate_x / 2, -plate_y / 2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_nx - 1])
        for (j = [0 : peg_ny - 1])
            translate([grid_x0 + i * peg_pitch,
                       grid_y0 + j * peg_pitch,
                       plate_t - overlap])
                cylinder(d = peg_d, h = peg_h + overlap, $fn = 64);
}
