$fn = 64;

plate_x     = 105;   // base plate length in X
plate_y     = 105;   // base plate length in Y
plate_t     = 5;     // base plate thickness (z = 0 to 5)

peg_d       = 10;    // peg diameter
peg_top     = 55;    // peg top height (z)
peg_nx      = 4;     // pegs along X
peg_ny      = 4;     // pegs along Y
peg_pitch   = 25;    // centre-to-centre spacing
overlap     = 0.5;   // peg sink into plate for clean union

union() {
    // Base plate
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Peg grid
    for (i = [0 : peg_nx - 1], j = [0 : peg_ny - 1])
        translate([(i - (peg_nx - 1)/2) * peg_pitch,
                   (j - (peg_ny - 1)/2) * peg_pitch,
                   plate_t - overlap])
            cylinder(d = peg_d, h = peg_top - plate_t + overlap);
}
```

