```openscad
// Adjustable shim plate with two rounded-end bolt slots
// Units: mm. Print orientation: flat on bed, z = 0 up to plate thickness.

// ---------- Plate ----------
plate_length    = 50;    // overall length along X
plate_width     = 30;    // overall width along Y
plate_thickness = 3;     // plate thickness along Z

// ---------- Slots ----------
slot_width      = 5.5;   // slot width (Y), also end-round diameter
slot_length     = 12;    // slot overall length end to end (X)
slot_x_positions = [-14, 14]; // slot centre X positions
slot_y          = 0;     // slot centre Y position

// ---------- Misc ----------
cut_extra       = 0.5;   // extension of cutters past faces
$fn             = 96;    // circle resolution

// Derived
slot_r          = slot_width / 2;              // end radius
slot_centre_gap = slot_length - slot_width;    // distance between end-circle centres

// Stadium-shaped slot cutter centred at (cx, cy)
module slot_cutter(cx, cy) {
    translate([cx, cy, -cut_extra])
        linear_extrude(height = plate_thickness + 2 * cut_extra)
            hull() {
                translate([-slot_centre_gap / 2, 0]) circle(r = slot_r);
                translate([ slot_centre_gap / 2, 0]) circle(r = slot_r);
            }
}

difference() {
    // Plate body, centred in X and Y, resting on z = 0
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thickness]);

    // Through-slots
    for (sx = slot_x_positions)
        slot_cutter(sx, slot_y);
}
```

