    // Stadium-shaped through-cut, extended above and below the plate
    translate([0, 0, -cut_ext])
        hull() {
            for (sx = [-slot_c2c / 2, slot_c2c / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * cut_ext);
        }
}

