```openscad
// Microplate riser
// Print orientation: legs on the bed (z = 0), top plate at z = 46..50

// ---------- Parameters ----------
plate_x      = 140;   // top plate length (X)
plate_y      = 100;   // top plate width (Y)
plate_t      = 4;     // top plate thickness
top_z        = 50;    // height of top face of plate
leg_size     = 15;    // square leg side length
window_x     = 100;   // central window length (X)
window_y     = 50;    // central window width (Y)
eps          = 0.5;   // cut overshoot to avoid coplanar faces
overlap      = 0.01;  // tiny leg/plate overlap for a clean union

leg_h        = top_z - plate_t;   // leg height (z = 0 to plate underside)

$fn = 64;

// ---------- Model ----------
union() {
    // Top plate with central window
    difference() {
        translate([-plate_x/2, -plate_y/2, top_z - plate_t])
            cube([plate_x, plate_y, plate_t]);
        translate([-window_x/2, -window_y/2, top_z - plate_t - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }

    // Four corner legs, flush with the plate's outer edges
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + overlap]);
}
```

```openscad
// Microplate riser
// Units: mm. Print orientation: legs down on the bed (z = 0), top plate up.

// ---------- Parameters ----------
plate_x      = 130;   // top plate length (X)
plate_y      = 95;    // top plate width (Y)
plate_t      = 5;     // top plate thickness
top_z        = 50;    // height of top face of plate
leg_size     = 10;    // square leg cross-section (X and Y)
window_x     = 90;    // centre window length (X)
window_y     = 55;    // centre window width (Y)
eps          = 0.5;   // cutter overshoot past faces
leg_overlap  = 0.01;  // tiny overlap of legs into plate for a clean union

$fn = 64;

// ---------- Derived ----------
plate_bot_z = top_z - plate_t;   // underside of the top plate (z = 45)
leg_h       = plate_bot_z;       // legs run from z = 0 to plate underside

// ---------- Modules ----------
module top_plate() {
    difference() {
        translate([-plate_x/2, -plate_y/2, plate_bot_z])
            cube([plate_x, plate_y, plate_t]);
        // central window, cut through with overshoot
        translate([-window_x/2, -window_y/2, plate_bot_z - eps])
            cube([window_x, window_y, plate_t + 2*eps]);
    }
}

module legs() {
    for (sx = [-1, 1], sy = [-1, 1]) {
        // legs flush with the plate's outer edges
        translate([sx > 0 ? plate_x/2 - leg_size : -plate_x/2,
                   sy > 0 ? plate_y/2 - leg_size : -plate_y/2,
                   0])
            cube([leg_size, leg_size, leg_h + leg_overlap]);
    }
}

// ---------- Assembly ----------
union() {
    top_plate();
    legs();
}
