```openscad
// Wall mounting strip with two countersunk screw holes
// Print orientation: flat on the bed, countersinks facing up (+Z)

// ---------- Dimensions (mm) ----------
bar_length   = 74;    // X length of the bar
bar_width    = 16;    // Y width of the bar
bar_thick    = 4;     // Z thickness of the bar

hole_count   = 2;     // number of screw holes
hole_pitch   = 50;    // centre-to-centre spacing along X
hole_d       = 5.5;   // through-hole diameter
csk_d        = 11;    // countersink diameter at top surface
csk_angle    = 90;    // included countersink angle (degrees)

eps          = 0.5;   // overshoot for clean boolean cuts
$fn          = 96;    // smoothness of curved surfaces

// ---------- Derived values ----------
// depth of a 90-degree countersink = (D - d) / 2 / tan(angle/2)
csk_depth    = (csk_d - hole_d) / 2 / tan(csk_angle / 2);
csk_r_top    = hole_d / 2 + (csk_depth + eps) * tan(csk_angle / 2); // radius at z = top + eps

// ---------- Model ----------
difference() {
    // Flat bar, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes along X at y = 0, centred on the bar
    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1) / 2) * hole_pitch;
        translate([x, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // Countersink cone, extended past the top face
            translate([0, 0, bar_thick - csk_depth])
                cylinder(r1 = hole_d / 2, r2 = csk_r_top, h = csk_depth + eps);
        }
    }
}
```

