notch_pitch    = 14;   // centre-to-centre spacing along X

eps            = 0.5;  // overshoot for clean cuts

$fn = 64;

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_length/2, -plate_width/2, 0])
        cube([plate_length, plate_width, plate_thick]);

    // Notches cut from the +Y edge, centred along X
    for (i = [0 : notch_count - 1]) {
        x_c = (i - (notch_count - 1) / 2) * notch_pitch;
        translate([x_c - notch_width/2,
                   plate_width/2 - notch_depth,
                   -eps])
            cube([notch_width, notch_depth + eps, plate_thick + 2*eps]);
    }
}
