flange_d   = 70;   // flange diameter (both flanges)
flange_t   = 2;    // flange thickness
core_d     = 25;   // core (winding drum) diameter
core_h     = 25;   // core height between flanges (z = 2 to z = 27)
bore_d     = 10;   // central through-bore diameter
eps        = 0.5;  // cutter overshoot past faces

// Derived
total_h    = flange_t + core_h + flange_t;  // 29 mm overall

difference() {
    union() {
        // Bottom flange: z = 0 to 2
        cylinder(d = flange_d, h = flange_t);

        // Core: z = 2 to 27 (slightly overlaps flanges for a clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_h + 0.02);

        // Top flange: z = 27 to 29
        translate([0, 0, flange_t + core_h])
            cylinder(d = flange_d, h = flange_t);
    }

    // Central through-bore along Z
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
